      "default": true
    },
    "copy_instruction": {
      "type": "boolean",
      "title": "Fence copyable text",
      "description": "Tell Claude to put anything meant to be copied (commands, messages, config) in a code block",
      "default": true
    },
    "tldr_button": {
      "type": "boolean",
      "title": "tl;dr button",
      "description": "Show a tl;dr button under long replies (one Sonnet call per click, cached)",
